// Some portions generated by Co-Pilot
import { render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import { getNewsPageData } from "@/utils/news";
import { formatDate } from "@/utils/date";
import LatestNews from "../index";

vi.mock("next-intl/server", () => ({
  getTranslations: vi.fn().mockResolvedValue((key: string) => key),
  getLocale: vi.fn().mockResolvedValue("en-GB"),
}));

vi.mock("@/utils/news", () => ({
  getNewsPageData: vi.fn(),
}));

const posts = Array.from({ length: 4 }, (_, index) => ({
  slug: `article-${index}`,
  year: "2026",
  month: "10",
  metadata: {
    title: `Article ${index}`,
    description: `Description for article ${index}`,
    date: `2026-10-${String(27 - index).padStart(2, "0")}`,
    author: "Adoptium",
  },
  content: "",
  readingTime: 1,
}));

describe("Latest news", () => {
  beforeEach(() => {
    vi.mocked(getNewsPageData).mockResolvedValue({
      posts,
      totalPages: 1,
      tags: [],
      authors: [],
    });
  });

  it("renders each article once across responsive layouts", async () => {
    const { container } = render(await LatestNews());
    expect(getNewsPageData).toHaveBeenCalledWith({ numPosts: 4 });
    expect(container.querySelectorAll("article")).toHaveLength(4);
    for (const post of posts) {
      expect(
        screen.getAllByRole("heading", { name: post.metadata.title }),
      ).toHaveLength(1);
      expect(
        screen.getByRole("link", { name: post.metadata.title }),
      ).toHaveAttribute(
        "href",
        `/news/${post.year}/${post.month}/${post.slug}`,
      );
    }
    expect(container.querySelector("button")).not.toBeInTheDocument();
  });

  it("features the newest story and provides an archive link", async () => {
    render(await LatestNews());
    expect(screen.getByText(posts[0].metadata.description)).toBeVisible();
    expect(
      screen.queryByText(posts[1].metadata.description),
    ).not.toBeInTheDocument();
    expect(screen.getByRole("link", { name: "see-all-news" })).toHaveAttribute(
      "href",
      "/news",
    );
  });

  it("renders localized dates with machine-readable values", async () => {
    const { container } = render(await LatestNews());
    const dates = container.querySelectorAll("time");
    expect(dates).toHaveLength(4);
    dates.forEach((date, index) => {
      expect(date).toHaveAttribute("datetime", posts[index].metadata.date);
      expect(date).toHaveTextContent(
        formatDate(posts[index].metadata.date, "en-GB"),
      );
    });
  });

  it("handles fewer stories without duplicating them", async () => {
    vi.mocked(getNewsPageData).mockResolvedValue({
      posts: posts.slice(0, 1),
      totalPages: 1,
      tags: [],
      authors: [],
    });
    const { container } = render(await LatestNews());
    expect(container.querySelectorAll("article")).toHaveLength(1);
    expect(screen.getAllByRole("link")).toHaveLength(2);
  });

  it("retains the archive link when there are no stories", async () => {
    vi.mocked(getNewsPageData).mockResolvedValue({
      posts: [],
      totalPages: 1,
      tags: [],
      authors: [],
    });
    const { container } = render(await LatestNews());
    expect(container.querySelectorAll("article")).toHaveLength(0);
    expect(screen.getByRole("link", { name: "see-all-news" })).toHaveAttribute(
      "href",
      "/news",
    );
  });

  it("has no accessibility violations", async () => {
    const { container } = render(await LatestNews());
    expect(await axe(container)).toHaveNoViolations();
  });
});
